// Normalize input (n8n Code node - JS)
// Run mode: runOnceForEachItem

// Accept both webhook wrapper and internal calls
const root = $json.body ? $json.body : $json;

// pick raw fields (some workflows put data under body, some don't)
const incomingSegment = root.segment || $json.segment || null;
const incomingFilterConfig = root.filter_config || $json.filter_config || null;
const incomingNeedAudio = (root.need_audio !== undefined) ? !!root.need_audio : ( $json.need_audio !== undefined ? !!$json.need_audio : true );
const incomingAudioFilePath = root.audioFilePath || $json.audioFilePath || null;

// If Probe Audio node is connected upstream, its output may be in the incoming item.
// Support either root.probe or root.probe_response or $json.probe
const probeObj = root.probe || root.probe_response || $json.probe || null;

// Helper to deep-clone
function clone(v) { return JSON.parse(JSON.stringify(v || {})); }

// Basic validation
if (!incomingSegment) throw new Error("segment missing in Normalize input");
if (!incomingFilterConfig) throw new Error("filter_config missing in Normalize input");

// Start normalized object
const normalized = {
  // raw normalized roots
  segment: clone(incomingSegment),
  filter_config: clone(incomingFilterConfig),
  // audio control
  need_audio: incomingNeedAudio,
  audioFilePath: incomingAudioFilePath || null,
  // will be filled with durations (seconds, float)
  segment_duration: null,
  audio_duration: null,
  // convenience meta defaults
  meta: {},
};

// --- 1) ensure filter_config is an object (sometimes stringified) ---
if (typeof normalized.filter_config === 'string') {
  try {
    normalized.filter_config = JSON.parse(normalized.filter_config);
  } catch (err) {
    throw new Error("filter_config is a string but JSON.parse failed: " + err.message);
  }
}

// provide defaults in meta / timing for downstream
normalized.meta = normalized.filter_config.meta = normalized.filter_config.meta || {};
normalized.timing = normalized.filter_config.timing = normalized.filter_config.timing || {};
normalized.filter_config.visual_overlays = normalized.filter_config.visual_overlays || {};
normalized.filter_config.text_overlays = normalized.filter_config.text_overlays || {};
normalized.filter_config.audio_overlays = normalized.filter_config.audio_overlays || {};
normalized.filter_config.transitions_overlays = normalized.filter_config.transitions_overlays || {};

// --- 2) If arrays are used for overlays, convert to keyed objects ---
// Accept either array or object; convert arrays to { visual_0: {...}, ... }
function ensureKeyed(obj, prefix) {
  if (!obj) return {};
  if (Array.isArray(obj)) {
    const out = {};
    for (let i = 0; i < obj.length; i++) {
      out[`${prefix}_${i}`] = obj[i];
    }
    return out;
  }
  return obj;
}

normalized.filter_config.visual_overlays = ensureKeyed(normalized.filter_config.visual_overlays, 'visual');
normalized.filter_config.text_overlays = ensureKeyed(normalized.filter_config.text_overlays, 'text');

// --- 3) Compute/attach scale_factor if only scale string exists ---
// e.g. "1920:1080" -> compute factor relative to meta.resolution width
function computeScaleFactorFromScale(scaleStr, metaResolution) {
  if (!scaleStr) return undefined;
  try {
    if (typeof scaleStr === 'string') {
      if (scaleStr.includes('iw*')) {
        const m = scaleStr.match(/iw\*([0-9.]+)/);
        if (m) return Number(m[1]);
      } else if (scaleStr.includes(':')) {
        const [wStr] = scaleStr.split(':');
        const targetW = parseFloat(wStr);
        const baseW = metaResolution ? parseFloat((metaResolution || '1920:1080').split(':')[0]) : 1920;
        if (!isNaN(targetW) && !isNaN(baseW) && baseW > 0) {
          return targetW / baseW;
        }
      }
    }
  } catch (e) {
    return undefined;
  }
  return undefined;
}

const metaRes = normalized.meta.resolution || '1920:1080';

// normalize visuals
for (const [k, v] of Object.entries(normalized.filter_config.visual_overlays || {})) {
  // ensure the overlay has a stable id (if you want we can use the key)
  v.id = v.id || k;

  // if they use "scale_factor", keep it; otherwise compute from "scale"
  if (v.scale_factor == null && v.scale) {
    const f = computeScaleFactorFromScale(v.scale, metaRes);
    if (f) v.scale_factor = f;
  }
  // ensure layer is numeric
  v.layer = typeof v.layer === 'number' ? v.layer : (isNaN(Number(v.layer)) ? 0 : Number(v.layer));
  // defaults
  v.x_offset_percent = v.x_offset_percent ?? 0;
  v.y_offset_percent = v.y_offset_percent ?? 0;
  v.opacity = v.opacity ?? 100;
}

// normalize texts
for (const [k, t] of Object.entries(normalized.filter_config.text_overlays || {})) {
  t.id = t.id || k;
  t.layer = typeof t.layer === 'number' ? t.layer : (isNaN(Number(t.layer)) ? 0 : Number(t.layer));
  t.x_offset_percent = t.x_offset_percent ?? 0;
  t.y_offset_percent = t.y_offset_percent ?? 0;
  t.opacity = t.opacity ?? 100;
  // compute scale_factor for texts if provided as scale string
  if (t.scale_factor == null && t.scale) {
    const f = computeScaleFactorFromScale(t.scale, metaRes);
    if (f) t.scale_factor = f;
  }
}

// --- 4) If Probe Audio was attached upstream, parse audio duration & set segment duration ---
// Probe output may be present as { response: { stdout: '...json...' } } or as plain object
let audioDuration = null;
try {
  const probeCandidate = probeObj || root.probe || $json.probe;
  if (probeCandidate) {
    // If it's a full node response with response.stdout
    const stdout = probeCandidate.response?.stdout || probeCandidate.stdout || null;
    if (stdout) {
      // many of your probe code print JSON: { "audio_duration": 14.904, "fade_start": "13.90" }
      try {
        const parsed = JSON.parse(stdout);
        if (parsed?.audio_duration) audioDuration = Number(parsed.audio_duration);
      } catch (e) {
        // maybe stdout is plain number string
        const n = Number(stdout);
        if (!isNaN(n)) audioDuration = n;
      }
    } else if (probeCandidate.audio_duration) {
      audioDuration = Number(probeCandidate.audio_duration);
    }
  }
} catch (e) {
  // ignore
}

// If audio duration found - set both audio_duration and segment_duration
if (audioDuration != null && !isNaN(audioDuration)) {
  normalized.audio_duration = audioDuration;
  normalized.segment_duration = audioDuration;
}

// If there's no audio but filter_config.meta has an explicit duration, use it
if (!normalized.segment_duration && normalized.meta && normalized.meta.segment_duration) {
  normalized.segment_duration = Number(normalized.meta.segment_duration);
}

// Last fallback: if no duration known -> leave null; CreateCompose will use default
// But set a sensible default in meta so image -t will not be zero
normalized.segment_duration = normalized.segment_duration || (normalized.meta.default_segment_duration || (normalized.meta?.default_preview_duration || 10));

// --- 5) If need_audio is true but audioFilePath not yet present, try to find it from root or upstream nodes ---
// Accept common variable names: audioFilePath, audio_file, audio_url
if (normalized.need_audio && !normalized.audioFilePath) {
  normalized.audioFilePath = root.audioFilePath || root.audio_file || root.audio_url || $json.audioFilePath || null;
}

// --- 6) Make sure meta contains fps/resolution/default_scale from defaults ---
normalized.meta.fps = normalized.meta.fps ?? 30;
normalized.meta.resolution = normalized.meta.resolution ?? '1920:1080';
normalized.meta.default_scale = normalized.meta.default_scale ?? '600:-1';

// --- 7) Return normalized structure for the CreateCompose node to consume ---
return {
  normalized
};

// n8n Code node: Create compose_request_body (improved)
// Expects input: normalized (from Normalize input node)
// Returns: { compose_request_body: { inputs, outputs, metadata, global_options, id } }

const root = $json.normalized || $json; // support two shapes
const seg = root.segment;
const filterConfig = root.filter_config || {};
const meta = filterConfig.meta || {};
const timing = filterConfig.timing || {};
const res = meta.resolution || "1920:1080";
const fps = meta.fps || 30;
const defScale = meta.default_scale || "600:-1";
const delaySeconds = Number(meta.delay_seconds || 0);
const chDur = Number(timing.chapter_transition_duration || 3);
const debug = !!meta.enable_debug_overlay;
const durationFallback = root.segment_duration || 10;

// ---------- helpers ----------
const clamp01 = (v) => Math.min(1, Math.max(0, isNaN(v) ? 1 : +v));
const lanczos = (s) => (s && s.includes("flags=") ? s : `${s || defScale}:flags=lanczos`);

// old center() -> FFmpeg expression generator (text-aware)
const center = (x = 0, y = 0, txt = false) => {
  const xp = (x / 100).toFixed(6);
  const yp = (-y / 100).toFixed(6); // ffmpeg positive up => subtract
  return {
    x: txt ? `(W-text_w)/2+(W*${xp})` : `(W-w)/2+(W*${xp})`,
    y: txt ? `(H-text_h)/2+(H*${yp})` : `(H-h)/2+(H*${yp})`
  };
};

// segment match() exactly as old code
const match = (o, s) =>
  (!o.segment_targets && !o.scene_types && !o.chapter_numbers) ||
  (Array.isArray(o.segment_targets) && o.segment_targets.includes(s.segment_number)) ||
  (Array.isArray(o.scene_types) && o.scene_types.includes(s.scene_type)) ||
  (Array.isArray(o.chapter_numbers) && o.chapter_numbers.includes(s.chapter_number));

// safe getter for overlay groups (object or array -> object keyed)
function ensureKeyed(obj) {
  if (!obj) return {};
  if (Array.isArray(obj)) {
    const out = {};
    for (let i = 0; i < obj.length; i++) out[`item_${i}`] = obj[i];
    return out;
  }
  return obj;
}

// flatten overlays into entries sorted by layer
const visualCfg = ensureKeyed(filterConfig.visual_overlays);
const textCfg   = ensureKeyed(filterConfig.text_overlays);
const audioCfg  = filterConfig.audio_overlays || {};
const transitionCfg = filterConfig.transitions_overlays || filterConfig.transitions || {};

// merge visuals + texts for overlay processing (texts are handled as drawtext later)
const overlaysObj = { ...visualCfg, ...textCfg };
const ovEntries = Object.entries(overlaysObj).sort((a, b) => ( (a[1].layer||0) - (b[1].layer||0) ));

// ---------- build inputs ----------
const inputs = [];
const ovs = []; // { key, i, o, t } for visual/video/image overlays
for (const [k, oRaw] of ovEntries) {
  const o = { ...oRaw };
  if (!match(o, seg)) continue; // segment-aware matching

  // skip pure text overlays for input stream building
  if (o.type === "text") continue;

  if (!o.url) continue;
  const t = o.type || (o.url.toLowerCase().endsWith(".mp4") ? "video" : "image");
  const opt = [];
  // compute duration to use for -t for images
  const dur = String(durationFallback);

  if (t === "image") {
    // images loop: use -loop 1 + -t <duration>
    opt.push({ option: "-loop", argument: "1" }, { option: "-t", argument: dur });
  }
  if (t === "video" && o.loop) {
    opt.push({ option: "-stream_loop", argument: "-1" });
  }
  inputs.push({ file_url: o.url, options: opt });
  ovs.push({ key: k, i: inputs.length - 1, o, t });
}

//
// narration audio (if present)
let audioIndex = null;
if (root.need_audio !== false && root.audioFilePath) {
  inputs.push({ file_url: root.audioFilePath, options: [] });
  audioIndex = inputs.length - 1;
}

// background music optional (choose first bg music matching scope)
let bgIdx = null;
const bgCfg = (Array.isArray(audioCfg) ? audioCfg.find(a=>a.id==='background_music') : (audioCfg && audioCfg.background_music)) || null;
if (bgCfg && (!bgCfg.scope || bgCfg.scope === seg.scene_type || bgCfg.scope === "all" || bgCfg.scope === "chapter")) {
  inputs.push({ file_url: bgCfg.url, options: [] });
  bgIdx = inputs.length - 1;
}

// any other audio overlays (e.g. sfx) may be treated as extra inputs (optional)
const otherAudioInputs = [];
if (Array.isArray(filterConfig.audio_overlays)) {
  filterConfig.audio_overlays.forEach(a=>{
    if (a.id !== (bgCfg && bgCfg.id)) {
      inputs.push({ file_url: a.url, options: [] });
      otherAudioInputs.push(inputs.length - 1);
    }
  });
} else if (typeof filterConfig.audio_overlays === 'object') {
  for (const [ak, a] of Object.entries(filterConfig.audio_overlays)) {
    if (a && a.url && a.id !== (bgCfg && bgCfg.id) && ak !== 'background_music') {
      inputs.push({ file_url: a.url, options: [] });
      otherAudioInputs.push(inputs.length - 1);
    }
  }
}

// ---------- filter_complex builder ----------
const parts = [];
let cur = null;
let tmp = 0;

// precompute center expression for each overlay and push scale+effects
for (const { i, o, t } of ovs) {
  const xOff = o.x_offset_percent ?? 0;
  const yOff = o.y_offset_percent ?? 0;
  const pos = center(xOff, yOff, false); // for visuals use w/h; text uses text_w/text_h later

  // scale: either explicit scale string, or use scale_factor -> convert to "iw*factor:ih*factor"
  let scaleStr = o.scale || defScale;
  if (!o.scale && o.scale_factor) {
    scaleStr = `iw*${o.scale_factor}:ih*${o.scale_factor}`;
  }

  let f = `[${i}:v]scale=${lanczos(scaleStr)},setsar=1,setpts=PTS-STARTPTS`;
  if (o.colorkey) f += `,colorkey=${o.colorkey}`;
  if (o.opacity != null && o.opacity < 100) {
    const aa = clamp01(o.opacity / 100);
    f += `,format=rgba,colorchannelmixer=aa=${aa}`;
  }
  f += `[ov${i}]`;
  parts.push(f);

  if (!cur) cur = `ov${i}`;
  else {
    tmp++;
    const next = `tmp${tmp}`;
    // overlay with position expression
    parts.push(`[${cur}][ov${i}]overlay=${pos.x}:${pos.y}:format=auto[${next}]`);
    cur = next;
  }
}

// if no overlays produced a video stream, use a fallback black screen (rare)
if (!cur) {
  // create a solid color background fallback using color source (ffmpeg supports color source with lavfi)
  // But since compose endpoint expects inputs[] entries, better to throw to highlight config issues:
  throw new Error("No overlays matched segment (no visual inputs).");
}

// ---------- CHAPTER / TEXT drawtext rendering (text_w/text_h-aware) ----------
// handle text overlays (drawtext) - iterate textCfg entries and apply only those matching segment
for (const [tk, tcfg] of Object.entries(textCfg)) {
  const t = { ...(tcfg || {}) };
  if (!match(t, seg)) continue;
  // ensure id
  t.id = t.id || tk;
  const pos = center(t.x_offset_percent ?? 0, t.y_offset_percent ?? 0, true);
  const font = t.font || "/app/fonts/ComicNeue-BoldItalic.ttf";
  const color = t.fontcolor || "white";
  const size = t.fontsize || 48;
  const box = t.box ? "box=1:" : "";
  const bc = t.boxcolor ? `boxcolor=${t.boxcolor}:` : "";
  const bb = t.boxborderw ? `boxborderw=${t.boxborderw}:` : "";
  const prefix = `${box}${bc}${bb}`.replace(/:+$/, "");
  const textSource = (() => {
    if (!t.text && t.text_source === "seg.chapter_name") return seg.chapter_name || "";
    if (t.text) return t.text;
    return seg.chapter_name || "";
  })();
  const safeText = String(textSource).replace(/'/g, "\\'");
  tmp++;
  const next = `tmp${tmp}`;
  parts.push(
    `[${cur}]drawtext=fontfile='${font}':text='${safeText}':fontcolor=${color}:fontsize=${size}:x=${pos.x}:y=${pos.y}:${prefix}[${next}]`
  );
  cur = next;
}

// ---------- CHAPTER ANIMATION (restore full intro|full|intro_and_full) ----------
const chapterAnim = transitionCfg?.chapter_animation || filterConfig.chapter_animation || {};
if (seg.scene_type === "chapter" && chapterAnim?.enable) {
  const mode = chapterAnim.mode || "intro";
  const introDur = (typeof chapterAnim.duration === "number") ? chapterAnim.duration : chDur;
  const persistentOpacity = (typeof chapterAnim.persistent_opacity === "number")
    ? clamp01(chapterAnim.persistent_opacity / 100) : 1;
  const pos = center((chapterAnim.offset?.x) ?? 0, (chapterAnim.offset?.y) ?? 0, true);
  const font = chapterAnim.font || "/app/fonts/ComicNeue-BoldItalic.ttf";
  const color = chapterAnim.fontcolor || "white";
  const size = chapterAnim.fontsize || 72;
  const box = chapterAnim.box ? "box=1:" : "";
  const bc = chapterAnim.boxcolor ? `boxcolor=${chapterAnim.boxcolor}:` : "";
  const bb = chapterAnim.boxborderw ? `boxborderw=${chapterAnim.boxborderw}:` : "";
  const prefix = `${box}${bc}${bb}`.replace(/:+$/, "");
  const rawText = (() => {
    if (!chapterAnim.text_source || chapterAnim.text_source === "seg.chapter_name") return seg.chapter_name || "";
    if (chapterAnim.text_source.startsWith("literal:")) return chapterAnim.text_source.replace(/^literal:/, "");
    if (chapterAnim.text_source.startsWith("meta.")) {
      const k = chapterAnim.text_source.replace(/^meta\./, "");
      return meta[k] || "";
    }
    return seg.chapter_name || "";
  })();
  const ttext = String(rawText).replace(/'/g, "\\'");

  if (mode === "intro") {
    tmp++;
    const next = `tmp${tmp}`;
    const enableExpr = `between(t,0,${introDur})`;
    parts.push(
      `[${cur}]drawtext=fontfile='${font}':text='${ttext}':fontcolor=${color}:fontsize=${size}:x=${pos.x}:y=${pos.y}:${prefix}:enable='${enableExpr}'[${next}]`
    );
    cur = next;
  } else if (mode === "full") {
    tmp++;
    const next = `tmp${tmp}`;
    let pc = color;
    if (persistentOpacity < 1 && !String(color).includes("@")) pc = `${color}@${persistentOpacity}`;
    parts.push(
      `[${cur}]drawtext=fontfile='${font}':text='${ttext}':fontcolor=${pc}:fontsize=${size}:x=${pos.x}:y=${pos.y}:${prefix}[${next}]`
    );
    cur = next;
  } else if (mode === "intro_and_full") {
    tmp++;
    const nextIntro = `tmp${tmp}`;
    const enableExpr = `between(t,0,${introDur})`;
    parts.push(
      `[${cur}]drawtext=fontfile='${font}':text='${ttext}':fontcolor=${color}:fontsize=${size}:x=${pos.x}:y=${pos.y}:${prefix}:enable='${enableExpr}'[${nextIntro}]`
    );
    cur = nextIntro;
    tmp++;
    const nextPersist = `tmp${tmp}`;
    let pc2 = color;
    if (persistentOpacity < 1 && !String(color).includes("@")) pc2 = `${color}@${persistentOpacity}`;
    const persistSize = Math.max(12, Math.round(size * 0.6));
    parts.push(
      `[${cur}]drawtext=fontfile='${font}':text='${ttext}':fontcolor=${pc2}:fontsize=${persistSize}:x=${pos.x}:y=${pos.y}:${prefix}[${nextPersist}]`
    );
    cur = nextPersist;
  }
}

// ---------- DEBUG overlay ----------
if (debug) {
  tmp++;
  const next = `tmp${tmp}`;
  parts.push(
    `[${cur}]drawtext=text='Seg:${seg.segment_number} Ch:${seg.chapter_number} ${seg.scene_type}':x=20:y=H-th-40:fontcolor=white:fontsize=28:box=1:boxcolor=black@0.4[${next}]`
  );
  cur = next;
}

// ---------- AUDIO handling (narration + background music + fades + adelay) ----------
const aIdx = audioIndex;
if (bgIdx !== null) {
  const vol = (bgCfg && (bgCfg.volume ?? 0.2)) || 0.2;
  const fadeIn = (bgCfg && (bgCfg.fade_in ?? 0)) || 0;
  const fadeOut = (bgCfg && (bgCfg.fade_out ?? 0)) || 0;
  // background: loop indefinitely + apply volume + fade
  let bgChain = `[${bgIdx}:a]aloop=loop=-1:size=2e+09,volume=${vol}`;
  if (fadeIn > 0) bgChain += `,afade=t=in:st=0:d=${fadeIn}`;
  if (fadeOut > 0) bgChain += `,afade=t=out:st=${Math.max(0, durationFallback - fadeOut)}:d=${fadeOut}`;
  bgChain += `[bgaud]`;
  parts.push(bgChain);

  // narration (adelay for first segment)
  if (aIdx != null) {
    if (seg.segment_number === 1 && delaySeconds > 0) {
      const ms = Math.round(delaySeconds * 1000);
      parts.push(`[${aIdx}:a]adelay=${ms}|${ms}[narr_aud]`);
    } else {
      parts.push(`[${aIdx}:a]anull[narr_aud]`);
    }
  } else {
    // no narration; create silent narration so amix works (not ideal but keeps graph)
    parts.push(`anullsrc=channel_layout=stereo:sample_rate=48000[silent_narr]`);
    parts.push(`[silent_narr]aresample=48000[narr_aud]`);
  }

  // if other audio inputs exist, map them into bg mix chain (optional)
  // Mix narration + bg (and any other audios if present) -> aout
  const amixInputs = [ '[narr_aud]', '[bgaud]' ];
  parts.push(`${amixInputs.join('')}amix=inputs=2:duration=shortest:dropout_transition=3[aout]`);
} else {
  // narration only path
  if (aIdx != null) {
    if (seg.segment_number === 1 && delaySeconds > 0) {
      const ms = Math.round(delaySeconds * 1000);
      parts.push(`[${aIdx}:a]adelay=${ms}|${ms}[aout]`);
    } else {
      parts.push(`[${aIdx}:a]anull[aout]`);
    }
  } else {
    // no audio at all, produce silent audio
    parts.push(`anullsrc=channel_layout=stereo:sample_rate=48000[aout]`);
  }
}

// ---------- FINAL OUTPUT scaling/pad and audio resample ----------
parts.push(`[${cur}]scale=${res}:force_original_aspect_ratio=decrease,pad=${res}:(ow-iw)/2:(oh-ih)/2,fps=${fps},setsar=1,format=yuv420p[vout]`);
parts.push(`[aout]aresample=48000,pan=stereo|c0=c0|c1=c0[aout_mapped]`);

// assemble filter_complex
const filterComplex = parts.join("; ");

// outputs options (map vout + aout_mapped)
const outputs = [
  {
    options: [
      { option: "-filter_complex", argument: filterComplex },
      { option: "-map", argument: "[vout]" },
      { option: "-map", argument: "[aout_mapped]" },
      { option: "-c:v", argument: "libx264" },
      { option: "-preset", argument: meta.preset || "veryfast" },
      { option: "-crf", argument: String(meta.crf || 20) },
      { option: "-c:a", argument: "aac" },
      { option: "-b:a", argument: meta.audioBitrate || "192k" },
      { option: "-ar", argument: "48000" },
      { option: "-ac", argument: "2" },
      { option: "-shortest" },
      { option: "-movflags", argument: "+faststart" }
    ]
  }
];

// dynamic id naming
const id = `ch${seg.chapter_number ?? 0}_seg${seg.segment_number ?? 0}_${seg.scene_type ?? "seg"}.mp4`;

// final compose_request_body
return {
  compose_request_body: {
    inputs,
    outputs,
    global_options: [{ option: "-y" }, { option: "-async", argument: "1" }],
    metadata: { duration: true, filesize: true },
    id
  }
